def isPrime(x):
    if x < 2:
        return False
    elif x == 2:
        return True  
    for n in range(2, x):
        if x % n ==0:
            return False
    return True

def primeGenerator(a, b):
    # 输出a,b 之间的素数，注意包含a, 不包含b
    for i in range(a, b):
        if isPrime(i):
            yield i
    
f = int(input())
t = int(input())

print(list(primeGenerator(f, t)))
